def min_cost(cost, m, n):
    cost[m][n] = 0  # Initialize the last cell cost as 0
    # Traverse through the matrix from right-bottom to left-top
    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            # Update the cost if a smaller cost is found either below or right
            if i+1 < m:
                cost[i][j] = min(cost[i][j], cost[i+1][j] + cost[i][j])
            if j+1 < n:
                cost[i][j] = min(cost[i][j], cost[i][j+1] + cost[i][j])
    return cost[0][0]  # Return the minimum cost from the top-left corner of the matrix

