def coin_change(coins, target, amount):
    def top_down(coins, target, amount):
        # Base cases
        if target == 0:
            return 1
        if amount == 0:
            return 0
        if target < 0 or not coins:
            return 0

        # Recursive case: pick or don't pick
        return top_down(coins, target - coins[-1], amount) + \
               top_down(coins[:-1], target, amount)

    # Wrapper function with memoization
    memo = [[0] * (amount + 1) for _ in range(len(coins) + 1)]
    def with_memo(coins, target, amount, memo):
        if target == 0:
            return 1
        if amount == 0:
            return 0
        if target < 0 or not coins:
            return 0

        if memo[amount][coin] > 0:
            return memo[amount][coin]

        memo[amount][coin] = with_memo(coins, target - coins[-1], amount, memo) + \
                             with_memo(coins[:-1], target, amount, memo)

        return memo[amount][coin]

    return top_down(coins, target, amount) if amount == target else with_memo(coins, target, amount, memo)
```

