def sum_of_odd_Factors(n):
    # Initialize sum to 1 (since 1 is a factor of every number)
    sum = 1
    # Remove all the even factors
    while n % 2 == 0:
        n //= 2
    # Now, n is odd, start from 3 and add all odd factors
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            sum += i
            while n % i == 0:
                n //= i
    # If n is a prime number greater than 2
    if n > 2:
        sum += n
    return sum
```

