from collections import Counter

def check(arr, n):
    digit_count = Counter(arr)
    sorted_digits = Counter(range(1, n+1)).values()

    if len(digit_count) != len(sorted_digits):
        return False

    sorted_arr = sorted(range(1, n+1))
    for k, v in digit_count.items():
        if k in sorted_arr:
            if v > sorted_digits[sorted_arr.index(k)]:
                return False
        else:
            the_remaining = sorted_digits[len(sorted_arr)-sorted_digits.index(k)]
            if the_remaining < v:
                return False

    return True
