def check(arr, size):
    # Check if the length of the array is less than 2
    if size < 2:
        return True
    # Check if the array is already sorted
    if sorted(arr) == arr:
        return True
    # Check if the first element of the part is greater than the first element of the part below it
    # and the second element of the part is smaller than the second element of the part above it
    for i in range(1, size):
        if arr[i] < arr[i-1]:
            return False
    return True
