def find_Max(A, l, h):
    # If l is less than or equal to h then we have found the maximum element
    if (l <= h):
        if (A[l] > A[h]):
            # If l is greater than h, the largest element is at the beginning of the array
            return A[l]
        else:
            # Else, the largest element is at the resuence of the largest element in the right half of the array
            return find_Max(A, (l + h) // 2 + 1, h)
    return -1  # If no element is found
