    mid = (L+R)/2

    # If the mid element is greater than both the left and right elements,
    if A[mid] > A[L] and A[mid] > A[R]:
        return A[mid]

    # If the array is rotated then there are two halves and we need to separate them
    if A[L] <= A[mid]:
        return find_Max(A,L,mid)
    else:
        return find_Max(A,mid+1,R)
