def get_noOfways(n):
    ways = [0]*(n+1)
    ways[1] = 1
    ways[2] = 2
    ways[3] = 4
    for i in range(4,n+1):
        ways[i] = ways[i-1] + ways[i-2] + ways[i-3]
    return ways[n]
