def max_sum_pair_diff_lessthan_K(arr, K, ret):
    arr.sort()  # Sort the array in ascending order
    left, right = 0, len(arr) - 1
    ans = 0
    while left < right:
        if arr[right] - arr[left] <= K:
            ans += (arr[right] + arr[left]) * (right - left)
            left, right = left + 1, right - 1
        else:
            right -= 1
    return ans >= ret  # Return True if the maximum sum meets or exceeds the required threshold
