def lis_len(arr):
    # Initialize the list to keep track of the length of the LIS
    lis = [1] * len(arr)
    # Iterate through the array
    for i in range(1, len(arr)):
        # Iterate through the previous elements
        for j in range(i):
            # If the current element is greater than the previous element, update the LIS length
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)
    # Return the maximum length of the LIS
    return max(lis)

def dls_len(arr):
    # Initialize the list to keep track of the length of the DLS
    dls = [1] * len(arr)
    # Iterate through the array in reverse
    for i in range(len(arr) - 2, -1, -1):
        # Iterate through the subsequent elements
        for j in range(i + 1, len(arr)):
            # If the current element is greater than the subsequent element, update the DLS length
            if arr[i] > arr[j]:
                dls[i] = max(dls[i], dls[j] + 1)
    # Return the maximum length of the DLS
    return max(dls)
