def sum_even_odd(lst: List[int]) -> int:
    sum_even = 0
    sum_odd = 0
    count_even = 0
    count_odd = 0

    for num in lst:
        if num % 2 == 0:
            sum_even += num
            count_even += 1
        else:
            sum_odd += num
            count_odd += 1

    if count_even > 0:
        sum_even //= count_even
    if count_odd > 0:
        sum_odd //= count_odd

    return sum_even + sum_odd
