def find_kth(nums1, nums2, k, p, q):
    if p == len(nums1):  # If nums1 is exhausted, return an element from nums2
        return nums2[q + k - 1]
    if q == len(nums2):  # If nums2 is exhausted, return an element from nums1
        return nums1[p + k - 1]
    if k == 1:  # If k is 1, return the smaller of the first elements
        return min(nums1[p], nums2[q])

    mid1, mid2 = nums1[p + k // 2 - 1], nums2[q + k // 2 - 1]  # Get mid elements
    if mid1 < mid2:
        return find_kth(nums1, nums2, k - k // 2, p + k // 2, q)
    else:
        return find_kth(nums1, nums2, k - k // 2, p, q + k // 2)
