def assign_elements(t): 
    # Initialize a dictionary to store pairs and their corresponding elements
    pairs_dict = {} 

    # Iterate through the elements in the tuple
    for i in range(len(t) - 1, -1, -1): 
        # Check if current element is present in pairs_dict
        if t[i] not in pairs_dict: 
            # Check if the next element also exists in the rest part of the tuple
            if (i + 1) < len(t) and t[i + 1] not in pairs_dict: 
                pairs_dict[t[i]] = [t[i + 1]] 
            else: 
                pairs_dict[t[i]] = [] 
        else: 
            # Add the next element to the list of pairs_dict if it's not already present
            pairs_dict[t[i]].append(t[i + 1]) 

    # Return the dictionary containing pairs and their corresponding elements
    return pairs_dict 
