def bell_Number(n):
    bell_table = [0] * (n + 1)
    bell_table[0] = 1
    for i in range(1, n + 1):
        bell_table[i] = sum(bell_table[j - 1] * binomial_coefficient(n, j - 1) for j in range(1, i + 1))
    return bell_table[n]

def binomial_coefficient(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return binomial_coefficient(n - 1, k - 1) + binomial_coefficient(n - 1, k)
