def maxAverageOfPath(matrix, n):
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        matrix[i][0] = matrix[i][1] + matrix[i][0]
        matrix[i][n-1] = matrix[i][n-2] + matrix[i][n-1]
    matrix[0] = [0] * n
    matrix[n-1] = [0] * n
    for i in range(n):
        for j in range(1, n-1):
            matrix[i][j] = max(matrix[i][j-1], matrix[i-1][j]) + matrix[i][j]
    max_avg = matrix[0][n-1] / n
    for i in range(1, n):
        for j in range(1, n-1):
            max_avg = max(max_avg, (matrix[i][j] - matrix[i-1][j-1]) / n)
    return max_avg
