    max_avg = -1
    # Iterate over all possible start points
    for i in range(size):
        for j in range(size):
            # Iterate over all possible ending points
            for x in range(size):
                for y in range(size):
                    # Calculate the current path sum
                    path_sum = 0
                    path_length = 0
                    for moves in range(size ** 2):
                        # Get the current coordinates
                        if moves == 0:
                            curr_x, curr_y = i, j
