                        # Add the element in the current position to the path sum
                        path_sum += matrix[curr_x][curr_y]
                        # Increment the path length
                        path_length += 1
                    # Calculate the average of the current path
                    avg = path_sum / path_length
                    # Update the maximum average if the current average is greater
                    if max_avg < avg:
                        max_avg = avg
