def find_Min_Swaps binary_array, n):
    for i in range(n-1):
        # finding first 0 from i+1 to n-1 
        j = i+1
        while j<=n-1:
            if binary_array[j] == 0:
                break
            j += 1
        # now i and j are indexes to left and right of 0
        if j==n: 
            continue
        for k in range(i+1, j):
            # check if there is 1 at index k and swap with index i
            if binary_array[k] == 1: 
                binary_array[k], binary_array[i] = binary_array[i], binary_array[k] 
                i += 1
    return (n-i-1)
