def super_seq(x, y, m, n):
    # Using 2D DP to find the length of longest common subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if x[i - 1] == y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Calculate length of super sequence
    return m + n - dp[m][n]
