def rencontres_number(n, k):
    # Base cases: rencontres_number(n, 0) = n! for k=0
    if k == 0:
        return factorial(n)
    # Recurrence relation for rencontres_number(n, k)
    else:
        return n * rencontres_number(n-1, k-1) + rencontres_number(n-1, k)
