def rencontres_number(n, k):
    # Initialize a 2D array to store intermediary results
    C = [[0 for _ in range(k+1)] for _ in range(n+1)]

    # Base case: C[i][0] and C[0][j] are 1 for all i, j
    for i in range(n+1):
        C[i][0] = 1
    for j in range(k+1):
        C[0][j] = 1

    # Fill the C array by calculating rencontres numbers using the recurrence relation
    for i in range(1, n+1):
        for j in range(1, k+1):
            C[i][j] = C[i][j-1] + i * C[i-1][j]

    # The n-th rencontres number is C[n][k]
    return C[n][k]
```

