import math

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(n):
    """Find the sum of all prime divisors of a given number."""
    summation = 0
    # Divide n by 2 until n becomes odd
    while n % 2 == 0:
        summation += 2
        n = n // 2
    # Check for odd factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            summation += i
            n = n // i
    # If n is a prime number greater than 2
    if n > 2:
        summation += n
    return summation

