def sum_of_square(n):
    # Helper function to calculate binomial coefficient
    def binom(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1
        return binom(n-1, k-1) + binom(n-1, k)

    # Calculate the sum of squares of binomial coefficients
    total_sum = 0
    for k in range(n + 1):
        total_sum += binom(n, k) ** 2
    return total_sum
