def max_sum_of_three_consecutive(arr, n):
    # Check if the size of the array is less than 3
    if n < 3:
        return "The array's size must be at least 3."

    # Initialize the dp array
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the dp array
    for i in range(n):
        for j in range(i, n):
            # Base cases
            if i == j:
                dp[i][j] = arr[i]
            elif j == i + 1:
                dp[i][j] = max(arr[i], arr[j])
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i][j - 2] + arr[j])

    # The maximum value in the dp array
    return max(dp[i][j] for i in range(n) for j in range(i, n))
