def max_product(arr):
    # Initialize the highest and second highest products to negative infinity
    first_max = second_max = float('-inf')

    # Initialize the lowest and second lowest products to positive infinity
    first_min = second_min = float('inf')

    # Iterate through each number in the array
    for num in arr:
        # Update the highest products
        if num > first_max:
            second_max = first_max
            first_max = num
        elif num > second_max and num != first_max:
            second_max = num

        # Update the lowest products
        if num < first_min:
            second_min = first_min
            first_min = num
        elif num < second_min and num != first_min:
            second_min = num

    # Determine the maximum product of two integers
    if first_max * second_max > first_min * second_min:
        return (first_max, second_max)
    else:
        return (first_min, second_min)
```

