def max_product(nums):
    # Initialize the maximum and second maximum integers to negative infinity
    max_num, second_max = float('-inf'), float('-inf')
    # Initialize the minimum and second minimum integers to infinity
    min_num, second_min = float('inf'), float('inf')

    # Iterate through the array
    for num in nums:
        # Update the maximum and second maximum as needed
        if num > max_num:
            second_max, max_num = max_num, num
        elif num > second_max and num <= max_num:
            second_max = num
        # Update the minimum and second minimum as needed
        if num < min_num:
            second_min, min_num = min_num, num
        elif num < second_min and num >= min_num:
            second_min = num

    # Return the pair with the highest product
    return (max_num * second_max, min_num * second_min)
