def sum_Of_Primes(n):
    # Initialise a list to mark non-prime numbers
    is_prime = [True] * (n+1)
    p = 2

    # Loop through all numbers starting from 2
    while (p**2 <= n):
        # If is_prime[p] is not 0, it's a prime number
        if (is_prime[p] == True):
            # Mark multiples of p as non-prime
            for i in range(p**2, n+1, p):
                is_prime[i] = False
        p += 1

    # Filter prime numbers, sum them up and return the result
    return sum(i for i in range(2, n+1) if is_prime[i])
