def min_coins(arr, value, count):
    # Base case: if no value left, return 0 coins
    if value == 0:
        return count
    # If value is less than 0 or array is empty, we can't make the value, return infinity
    if value < 0 or not arr:
        return float('inf')
    # We have two choices: include the last coin or exclude it
    include = 1 + min_coins(arr, value - arr[-1], count)
    exclude = min_coins(arr[:-1], value, count)
    # Return the minimum of the two choices
    return min(include, exclude)
```

