def min_coins(coins, value, max_coin):
    if value == 0:
        return 0
    if coins[0] > value:
        return min_coins(coins[1:], value, max_coin)
    if coins[0] == value:
        return 1
    # non-choice case
    x = min_coins(coins, value - 1, max_coin)
    # choice case
    y = min_coins(coins, value - max_coin, max_coin)
    if x == 0:
        return y + 1
    return min(x, y + 1)
