def find_closet(arr1, arr2, arr3, x1, x2, x3):
    # Initialize pointers and minimum difference
    i, j, k = x1 - 1, x2, x3
    min_diff = float('inf')
    closest_elements = (float('inf'), float('inf'), float('inf'))

    # Traverse through the arrays
    while i < len(arr1) and j < len(arr2) and k < len(arr3):
        curr_diff = min(abs(arr1[i] - x1), abs(arr2[j] - x2), abs(arr3[k] - x3))
        if curr_diff < min_diff:
            min_diff = curr_diff
            closest_elements = sorted([arr1[i], arr2[j], arr3[k]])

        # Move the pointer of the array with the minimum difference
        if arr1[i] + arr2[j] + arr3[k] < x1 + x2 + x3:
            i += 1
        elif arr1[i] + arr2[j] + arr3[k] > x1 + x2 + x3:
            k += 1
        else:
            # If all elements are equal, the current combination is closest
            if min_diff == 0:
                return closest_elements
            return sorted([arr1[i], arr2[j], arr3[k]])

    # If the closest elements were found, return them
    return sorted(closest_elements)
