def lbs(nums):
    # Initialize the LIS array with 1 for all indices
    lis = [1] * len(nums)
    # Initialize the LDS array with 1 for all indices
    lds = [1] * len(nums)

    # Compute lis values from left to right
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Compute lds values from right to left
    for i in range(len(nums) - 2, -1, -1):
        for j in range(len(nums) - 1, i, -1):
            if nums[i] > nums[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # The maximum length of bitonic subsequence is the maximum value in the combination of lis and lds
    return max([lis[i] + lds[i] - 1 for i in range(len(nums))])
