    # Initialize the minimum cost dictionary
    min_cost_dict = {}

    # Recursive function to compute minimum cost
    def compute_min_cost(row, col):
        if (row, col) in min_cost_dict:
            return min_cost_dict[(row, col)]

        # Base case: end point reached
        if row == target_row and col == target_col:
            return cost[row][col]

        # Calculate minimum of left and bottom moves
        left_cost = compute_min_cost(row, col - 1) if col > 0 else float('inf')
        bottom_cost = compute_min_cost(row + 1, col) if row < len(cost) - 1 else float('inf')

        # Update minimum cost for the current position
        min_cost Dictionary[(row, col)] = cost[row][col] + min(left_cost, bottom_cost)
        return min_cost_dict[(row, col)]

    # Start the recursive computation from the start point
    return compute_min_cost(0, 0)
