def min_Swaps(source, target):
    # Initialize the result to store the number of swaps
    result = 0

    # Create a dictionary to map each position in the source string to its corresponding position in the target string
    map = {}
    n = len(source)

    # Populate the dictionary
    for i in range(n):
        map[i] = target[i]

    # Iterate through the source string
    for i in range(n):
        if map[i] != source[i]:
            # Count the number of swaps required to match the position
            for j in range(i+1, n):
                if map[j] == source[i]:
                    # Swap positions and update the result
                    map[i], map[j] = map[j], map[i]
                    result += 1
                    break

    # Return the total number of swaps required
    return result
