def hamming_distance(a, b):
    distance = 0
    while a > 0 and b > 0:
        if a % 2 != b % 2:
            distance += 1
        a = a >> 1
        b = b >> 1
    while a > 0:
        if a % 2 != 0:
            distance += 1
        a = a >> 1
    while b > 0:
        if b % 2 != 0:
            distance += 1
        b = b >> 1
    return distance

