def bell_Number(n):
    # Base case: Bell number for n=0
    if n == 0:
        return 1

    # Initialize the bell number array
    bell = [0] * (n + 1)
    bell[0] = 1

    # Calculate bell numbers
    for i in range(1, n + 1):
        bell[i] = sum(bell[j - 1] * binomial(i - 1, j - 1) for j in range(1, i + 1))

    return bell[n]

# A function to calculate binomial coefficient
def binomial(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return binomial(n - 1, k - 1) + binomial(n - 1, k)

# Test case
assert bell_Number(2) == 2
