    if n == 1:
        return 1
    if n == 0:
        return 1
    # Recursive calculation of rencontres numbers
    return rencontres_number(n-1, k) * (-k**n + 1) * (-k**n + 2 * k) // 2 * (-1)**(n - k) // (n - k + 2)
