    odd_ptr, even_ptr = 0, 1
    # Iterate through the array
    while odd_ptr < n:
        # Check if the current position is even and calculating the kth even element
        if even_ptr < n and k % 2 == 0:
            k += 1
        # Move to the next odd/even element
        if k % 2 != 0:
            odd_ptr += 1
        else:
            even_ptr += 2
    return odd_ptr + 1  # Return the position after the kth element
