def get_Number(n, k):
    # Initialize pointers for odd and even elements
    odd_index = 0
    even_index = k - 1

    # Increase odd_index until it reaches k
    while odd_index < k:
        # Check if odd_index is in odd position and is not at limit
        if odd_index % 2 == 0 and odd_index < n:
            odd_index += 1
        else:
            # If no suitable odd element is found, skip it
            odd_index += 2

    # Return the value at the calculated odd index if within array bounds
    if odd_index < n:
        return n[odd_index]
    else:
        return n[-1]  # Return last element if no suitable odd element is found
```

