    # Create a list of set to store unique elements for each subset
    res = []
    # Iterate through all possible subset sizes
    for i in range(1, n + 1):
        for j in range(n):
            # If the current subset has the i-th element
            if i > 0 and j in res[i-1][0]:
                # Remove the i-th element to consider the next smaller subset
                res[i-1][0].remove(j)
            # Union the subset with(j+1) to add new elements
            res[i-1].append(arr[j+1:])
            # Check if the current subset returns numbers greater than i
            for m in res[i-1][1]:
                if len(m) < i:
