def check(arr, n):
    if n == 1:
        return True

    # Pick the smallest element from the first half
    smallest = arr[0]
    for i in range(n):
        if arr[i] < smallest:
            smallest = arr[i]

    # Pick the largest element from the second half
    largest = arr[-1]
    for i in range(n-1, -1, -1):
        if arr[i] > largest:
            largest = arr[i]

    # Move all elements less than or equal to the smallest to the beginning
    j = 0
    for i in range(n):
        if arr[i] <= smallest:
            arr[j], arr[i] = arr[i], arr[j]
            j += 1

    # Move all elements greater than to the end
    k = n - 1
    for i in range(n-1, -1, -1):
        if arr[i] >= largest:
            arr[k], arr[i] = arr[i], arr[k]
            k -= 1

    # Check if the array is sorted
    for i in range(1, n):
        if arr[i] < arr[i-1]:
            return False
    return True
```

