def find_First_Missing(arr, low, high):
    if low > high:
        return low + 1

    mid = (low + high) // 2

    # If the element at mid index equals its index, the missing number is in the right half
    if arr[mid] == mid:
        missing_number = find_First_Missing(arr, mid + 1, high)
    else:
        # If the element at mid index is less than index, the missing number is in the left half
        ambiguous_position = find_First_Missing(arr, low, mid)
        # If ambiguous_position is same as `mid+1`, then `mid` + 1 is the missing number
        if ambiguous_position == mid + 1:
            missing_number = mid + 1
        else:
            missing_number = find_First_Missing(arr, low, ambiguous_position - 1)

    return missing_number
```

