def find_First_Missing(nums, start, end):
    # Find the first number where nums[start:index] are consecutive
    while start < end:
        mid = (start + end) // 2
        if (nums[start] != mid and nums[mid+1] != mid+1) or (nums[start] == mid and nums[mid+1] == mid+1):
            return mid + 1
        elif nums[start] < mid:
            start = mid + 1
        else:
            end = mid - 1
    # If no missing number is found, it's the next number after the last index
    return start + 1
