def find_First_Missing(arr, start, end):
    """
    Finds the smallest missing number from the given array.

    Parameters:
    arr (list): The list of integers.
    start (int): The start index of the array.
    end (int): The end index of the array.

    Returns:
    int: The smallest missing number.
    """
    if start > end:
        return start

    mid = (start + end) // 2

    # If the element at mid is equal to mid
    if arr[mid] == mid:
        return find_First_Missing(arr, mid+1, end)

    else:
        return find_First_Missing(arr, start, mid-1)
