def max_sum_pair_diff_lessthan_K(arr, k, n):
    # Calculate the sum of elements in the array
    total_sum = sum(arr)
    # Find the maximum sum of disjoint pairs with a difference less than k
    max_sum = total_sum * (n // 2)
    # Subtract the sum of redundant pairs from the result
    for i in range(n):
        for j in range(i + 1, n):
