def find_Max(arr, l, r):
    # Base case if the search range is single element
    if l == r:
        return arr[l]

    # Find the middle index
    mid = (l + r) // 2

    # If mid is the maximum element
    if mid < r and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # If mid is the minimum element or the left half is sorted
    if mid > l and arr[mid - 1] > arr[mid]:
        return arr[mid - 1]

    # If the left half is not sorted, find the max in the right half
    if arr[l] > arr[mid]:
        return find_Max(arr, l, mid - 1)
    # Otherwise, find the max in the left half
    else:
        return find_Max(arr, mid + 1, r)
