def find_Points(x1_start, x1_end, y1_start, y1_end):
    # Randomly choose x points from x1 range
    x_points = {random.randint(x1_start, x1_end) for _ in range(5)}

    # Randomly choose y points from y1 range
    y_points = {random.randint(y1_start, y1_end) for _ in range(5)}

    # Find the points that are in both ranges
    common_points = x_points & y_points

    # Ensure no point lies in both ranges
    if common_points:
        while common_points:
            random_point = random.choice(common_points)
            x_points.remove(random_point)
            y_points.remove(random_point)
            common_points = x_points & y_points

    return (random.choice(x_points), random.choice(y_points))
