def sum_Of_product(n):
    # Initialize a list to store binomial coefficients
    binomial_coeffs = [1 for _ in range(n + 1)]
    # Calculate binomial coefficients using Pascal's triangle
    for i in range(1, n):
        for j in range(i):
            binomial_coeffs[j] = binomial_coeffs[j] + binomial_coeffs[j - 1]
    # Calculate the sum of product of binomial coefficients
    return sum(index * binomial_coeffs[index] for index in range(n + 1))
