        curr_a = a[i] if i < x else float('inf')
        curr_b = b[j] if j < y else float('inf')
        curr_c = c[k] if k < z else float('inf')

        # Find the smallest difference with the current element
        if compare(curr_a, curr_b) == -1:
            closest_elements = (curr_a, curr_b, curr_c)
        elif compare(curr_a, curr_c) == -1:
            closest_elements = (curr_a, curr_c, curr_b)
        elif compare(curr_b, curr_c) == -1:
            closest_elements = (curr_b, curr_c, curr_a)
