def find_kth(arr1, arr2, k, n1, n2):
    # Base cases
    if n1 == 0:
        return arr2[k-1]
    if n2 == 0:
        return arr1[k-1]

    # Determine the middle elements of both arrays
    mid1 = n1 // 2
    mid2 = n2 // 2

    # Compare the middle elements
    if arr1[mid1] <= arr2[mid2]:
        # If arr1's middle is smaller or equal, the kth element is in arr1 or after
        if mid1 + 1 < n1 and k > mid1 + 1:
            return find_kth(arr1, arr2[mid2+1:], k - mid1 - 1, n1, n2 - mid2 - 1)
        else:
            return find_kth(arr1[mid1+1:], arr2, k, n1 - mid1 - 1, n2)
    else:
        # If arr2's middle is smaller, the kth element is in arr2 or after
        if mid2 + 1 < n2 and k > mid2 + 1:
            return find_kth(arr1, arr2, k - mid2 - 1, n1, n2 - mid2 - 1)
        else:
            return find_kth(arr1, arr2[mid2+1:], k, n1, n2 - mid2 - 1)
```

