def find_kth(m, n, i, j, k):
    # If m index exceeds the length of the first array, search in the second array
    if i >= len(m):
        return n[j + k - 1]
    # If n index exceeds the length of the second array, search in the first array
    elif j >= len(n):
        return m[i + k - 1]
    # If k is 1, return the value at the current indices
    elif k == 1:
        return min(m[i], n[j])
    # Divide k by 2 to find the middle elements
    mid = k // 2
    # Compare the middle elements of both arrays
    if m[i] <= n[j]:
        return find_kth(m, n, i + mid, j, k - mid)
    else:
        return find_kth(m, n, i, j + mid, k - mid)
