def lbs(nums):
    n = len(nums)
    dp1 = [1] * n  # dp1[i] represents the length of the longest increasing subsequence ending at index i
    dp2 = [1] * n  # dp2[i] represents the length of the longest decreasing subsequence ending at index i

    # Build dp1
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j] and dp1[i] < dp1[j] + 1:
                dp1[i] = dp1[j] + 1

    # Build dp2
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if nums[i] > nums[j] and dp2[i] < dp2[j] + 1:
                dp2[i] = dp2[j] + 1

    # The length of the longest bitonic subsequence is max(dp1[i] + dp2[i] - 1) for all i
    lbs = max(dp1[i] + dp2[i] - 1 for i in range(n))
    return lbs
```

