def maxAverageOfPath(grid, size):
    def dfs(x, y, path_sum, path_len):
        nonlocal max_avg
        if path_len == size:
            if path_sum / path_len > max_avg:
                max_avg = path_sum / path_len
            return
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < size and 0 <= ny < size:
                dfs(nx, ny, path_sum + grid[nx][ny], path_len + 1)

    max_avg = 0
    for i in range(size):
        for j in range(size):
            dfs(i, j, grid[i][j], 1)
    return max_avg
