            return [path_str]
        paths = []
        for i in range(n):
            for j in range(n):
                if matrix[i][j] in path_str:
                    continue
                paths.extend(getPaths(path_str + str(matrix[i][j]), remaining - 1))
        return paths
    max_avg = 0
    for path_length in range(1, n + 1):
        for path in getPaths('', path_length):
            avg = sum(map(int, path)) / path_length
            if avg > max_avg:
                max_avg = avg
    return max_avg
