def coin_change(coins, amount, target):
    dp = [[0] * (target + 1) for _ in range(len(coins) + 1)]

    for i in range(1, len(coins) + 1):
        for j in range(target + 1):
            if j == 0:
                dp[i][j] = 1
            elif coins[i - 1] <= j:
                dp[i][j] = dp[i][j - coins[i - 1]] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[len(coins)][target]
