def coin_change(coins, amount, n_coins):
    # Create a 2D array to store the number of ways
    dp = [[0 for _ in range(amount + 1)] for _ in range(n_coins + 1)]

    # Base case
    for i in range(n_coins + 1):
        dp[i][0] = 1  # There's one way to make an amount of 0 (using no coins)

    # Fill the dp array
    for i in range(1, n_coins + 1):
        for j in range(1, amount + 1):
            if coins[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] + dp[i][j - coins[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n_coins][amount]
