def min_coins(coins, val, n):
    # If n is 0, return 0
    if val == 0:
        return 0

    # If value is less than the smallest coin, it's impossible to make the value
    if val < min(coins):
        return -1

    # Initialize the count of coins to infinity
    count = float('inf')

    # Explore all possible combinations of coins
    for i in range(n):
        if coins[i] <= val:
            sub_count = min_coins(coins, val - coins[i], n)
            if sub_count != -1:
                count = min(count, sub_count + 1)

    # If no combination was found, return -1
    if count == float('inf'):
        return -1

    return count
