def last_Two_Digits(n):
    # Base case: factorial of 0 or 1 is 1
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        # Initialize ans as 1
        ans = 1
        # Multiply by numbers from (n-1) down to 1
        for i in range(n-1, 0, -1):
            ans = (ans * i) % 256  # Update ans to last two digits of the product
        return ans % 100  # Return the last two digits of the final factorial result
