import math

def floor_Min(start_x, end_x, period):
    phase = math.floor((start_x - period * math.floor(start_x / period)) / period)
    displacement = displacement_from_phase(period, phase)
    phase_shift = phase_shift_from_distance(displacement)
    floor_min_mtime = floor(Monotonic_Time(start_x, end_x, period), phase_shift)
    return floor_min_mtime

def Monotonic_Time(start_x, end_x, period):
    return start_x + Orthogonally_divided(x - start_x, period)

def Orthogonally_divided(x, divisor):
    remainder = x % divisor
    quotient = math.floor(x / divisor) if remainder != 0 else math.floor(x / divisor) - 1
    return (quotient, remainder)

def displacement_from_phase(period, phase):
    return phase * period

def phase_shift_from_distance(distance):
    return math.sqrt(distance ** 2 + period ** 2)

def floor(value, shift):
    return math.floor(value + shift) if shift >= 0 else math.ceil(value - shift)
```

