def super_seq(str1, str2, len1, len2):
    # Create a 2D table to store lengths of LCS
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

    # Fill dp table
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the super sequence
    super_seq = ""
    i, j = len1, len2
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            super_seq = str1[i - 1] + super_seq
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            super_seq = str1[i - 1] + super_seq
            i -= 1
        else:
            super_seq = str2[j - 1] + super_seq
            j -= 1

    # Add remaining characters
    while i > 0:
        super_seq = str1[i - 1] + super_seq
        i -= 1
    while j > 0:
        super_seq = str2[j - 1] + super_seq
        j -= 1

    return len(super_seq)
