    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                dp[i][j] = j  # Empty string is added, so f[n][j] = j
            elif j == 0:
                dp[i][j] = i  # Empty string is added, so f[i][m] = i
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1  # Include character without increasing depth
