def super_seq(str1, str2, n, m):
    # Create a 2D list to store the lengths of subseqs
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Build the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the shortest superseq is n + m - dp[n][m]
    return n + m - dp[n][m]
```

