import math

def min_Jumps(x, y, d):
    if (y < 0) or (x < 0):
        return 0
    mxv = math.floor(math.sqrt(x * x + y * y))
    if mxv > d:
        return 0
    if mxv == d:
        if (x * x + y * y) == d:
            return 1
        else:
            return 0
    return math.ceil(math.log(d / mxv, 2))
