    found = False
    for i in range(length):
        if arr[i] == 1 or arr[i] == length:
            found = True
            break

    # Sort the array if '1' and 'length' are found
    if found:
        sorted_check = sorted(arr[0:length]) == arr[0:length]
        return sorted_check
    else:
        return False
```
