def check(arr, n):
    if n == 0:
        return True
    front = 0
    back = n - 1
    while (arr[front] <= arr[back]):
        front += 1
        if front == n:
            return True
        back -= 1
    for i in range(front, back + 1):
        if i != front and arr[i] < arr[i - 1]:
            return False
    for i in range(back, n):
        if i != back and arr[i] < arr[i + 1]:
            return False
    return True
