def join_tuples(test_tuples):
    # Create an empty list to store the results
    result = []
    # Dictionary to keep track of the groups
    group_dict = {}

    # Iterate over each tuple in the input list
    for t in test_tuples:
        # Check if the first element is already in the dictionary
        if t[0] in group_dict:
            # If so, update the set of values for that key
            group_dict[t[0]].add(t[1])
        else:
            # If not, create a new set with the current tuple's second element
            group_dict[t[0]] = {t[1]}

    # Convert the dictionary to a list of tuples, preserving order
    for key, values in group_dict.items():
        result.append(tuple([key]) + tuple(sorted(values)))

    return result
