def rencontres_number(n, k):
    max_value = 100000
    computed_values = [0] * max_value
    computed_values[0] = 1
    computed_values[1] = 1
    computed_values[2] = 1

    def set_value(val, n, k):
        if n < len(computed_values) and val > 0:
            computed_values[n] = val

    def is_valid_max_value(n, k):
        val = (3 * k * (2 * k - 1) * n * 12 * (2 * k + n - 1)) // (2 * k * (2 * k - 1) * n * (2 * k + n - 1) + 1)
        if val > computed_values[-1]:
            return True
        return False

    if is_valid_max_value(n, k):
        for i in range(3, max_value):
            next_val = 4 * (k - 1)**2 * k * i * (4 - 3 * k * i) // (4 * (k - 1)**2 * k * i * (4 - 3 * k * i) + 1)
            set_value(next_val, i, k)

    return next_val if n < len(computed_values) else computed_values[n] - 1
