def rencontres_number(n, m):
    # Initialize the number of ways for 0 to n people
    number_of_ways = [0] * (n + 1)
    number_of_ways[0] = 1

    # Calculate the number of ways for each number of people
    for people in range(1, n + 1):
        for rec_n in range(0, people):
            number_of_ways[people] += number_of_ways[rec_n] * number_of_ways[people - 1 - rec_n]

    # Multiply by m! to shift the recurrence relation
    return number_of_ways[n] * factorial(m)

