def rencontres_number(n, m):
    # Initialize the Pascali triangle with a matrix of zeros
    pascali triangle = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the Pascal triangle
    for i in range(n + 1):
        for j in range(i + 1):
            if j == 0 or j == i:
                pascali_triangle[i][j] = 1
            else:
                pascali_triangle[i][j] = pascali_triangle[i - 1][j - 1] + pascali_triangle[i - 1][j]

    # Calculate the n-th rencontres number
    result = 1
    for i in range(n, n + m):
        result *= (n - i + 2) / (i + 1)

    return int(result * pascali_triangle[n][m])
