    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    # List to store prime divisors
    prime_divisors = []
    # Iterate to find all prime divisors
    for divisor in range(2, n + 1):
        while is_prime(divisor) and n % divisor:
            prime_divisors.append(divisor)
            n //= divisor
    # Return the sum of prime divisors
    return sum(prime_divisors)

