        else:
            frequency[string] = 1

    # Find the most frequent and the second most frequent strings
    max_count = max(frequency.values())
    second_max_count = 0
    second_most_frequent = None

    for string, count in frequency.items():
        if count == max_count and string != second_most_frequent:
