def min_cost(cost, m, n):
    # Initialize the cost array to store the minimum cost to reach each cell
    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 0

    # Traverse the cost matrix to fill the dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                dp[i][j] = 0
            elif i == 0:
                dp[i][j] = dp[i][j - 1] + cost[0][j - 1]
            elif j == 0:
                dp[i][j] = dp[i - 1][j] + cost[i - 1][0]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + cost[i - 1][j - 1]

