def min_cost(cost, m, n):
    cache = [[None] * len(cost[0]) for _ in range(len(cost))]
    return min_cost_helper(cost, m, n, cache)

def min_cost_helper(cost, m, n, cache):
    if m == 0 and n == 0:
        return cost[0][0]
    if cache[m][n]:
        return cache[m][n]
    if m == 0:
        return cost[m][n] + min_cost_helper(cost, m, n - 1, cache)
    elif n == 0:
        return cost[m][n] + min_cost_helper(cost, m - 1, n, cache)
    else:
        cache[m][n] = cost[m][n] + min(min_cost_helper(cost, m, n - 1, cache), min_cost_helper(cost, m - 1, n, cache))
        return cache[m][n]
