def max_sum_of_three_consecutive(nums, n):
    if n < 3:
        return sum(nums)
    dp = [0] * n
    dp[0] = nums[0]
    dp[1] = nums[0] + nums[1]
    dp[2] = max(nums[0] + nums[2], nums[1] + nums[2])

    for i in range(3, n):
        dp[i] = max(nums[i] + dp[i-3], nums[i-1] + dp[i-2], dp[i-1])

    return max(dp)
