def dealnnoy_num(n, k):
    # Initialize the Delannoy matrix
    computer = [[0] * (k + 1) for _ in range(n + 1)]

    # Fill the matrix
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i <= j:
                computer[i][j] = computer[i-1][j] + computer[i-1][j-1] + computer[i][j-2]
