def min_Swaps(str1, str2):
    n = len(str1)
    already_matched = [-1] * n
    swap = 0

    def backtrack(i):
        # If all characters match
        if i == n:
            return swap

        # If character already matched, skip it
        if already_matched[i] != -1:
            return backtrack(i + 1)

        # Try each position to match with str2[i]
        for j in range(n):
            if str2[j] == str1[i]:
                swap += 1
                already_matched[i] = j
                break

        # Move to the next character
        return backtrack(i + 1)

    return backtrack(0)
```

