def min_Swaps(s1, s2):
    count = 0  # Initialize a counter to count swaps
    mismatch_positions = []  # List to store positions of mismatch

    # Find positions of mismatch
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            mismatch_positions.append(i)  # Store the position where the mismatch occurs

    # Calculate the number of swaps needed
    n = len(mismatch_positions)
    swaps = 0

    # Find pairs of mismatch and calculate swaps
    for i in range(n):
        if mismatch_positions[i] % 2 == 0:
            swaps += mismatch_positions[swaps] - mismatch_positions[i]
        else:
            swaps += mismatch_positions[i] - mismatch_positions[swaps - 1] - 1

    return swaps
