import math
def coin_change(coins, amount, total_coin):
    dp = [[0 for _ in range(total_coin + 1)] for _ in range(len(coins))]
    for i in range(len(coins)):
        for j in range(total_coin + 1):
            if j == 0:
                dp[i][j] = 1
            elif j < coins[i]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i][j - coins[i]] + dp[i - 1][j]
    return dp[len(coins) - 1][amount]
