from bisect import bisect_left

def find_closet(arr1, arr2, arr3, k, m, n):
    def closest_value(target, arr):
        index = bisect_left(arr, target)
        if index >= len(arr):
            return arr[index - 1], abs(target - arr[index - 1])
        if index < 0:
            return arr[index], abs(target - arr[index])
        return arr[index - 1], abs(target - arr[index])

    closest_one, _ = closest_value(arr1[0], arr1)
    closest_two, _ = closest_value(arr2[0], arr2)
    closest_three, _ = closest_value(arr3[0], arr3)

    result = (closest_one, closest_two, closest_three)
    for i in range(min(k, m)):
        new_one = closest_one
        new_two = closest_two
        new_three = closest_three
        if i < min(k, n):
            new_one = arr1[i]
            new_two = arr2[i]
            new_three = arr3[i]
        _, diff1 = closest_value(new_one, arr1)
        _, diff2 = closest_value(new_two, arr2)
        _, diff3 = closest_value(new_three, arr3)
        if diff1 < diff2 and diff1 < diff3:
            closest_one = new_one
            closest_two, closest_three = new_two, new_three
        elif diff2 < diff3:
            closest_two = new_two
            closest_three = new_three
        else:
            closest_three = new_three
    return result

