def maxAverageOfPath(matrix, n):
    max_avg = float('-inf')
    # Iterate over all possible starting points
    for i in range(n):
        for j in range(n):
            current_avg = 0
            # Calculate the average over all paths starting from (i, j)
            for _ in range(n):
                current_avg += matrix[i][j]
                if i > 0:
                    current_avg += matrix[i-1][j]
                if i < n-1:
                    current_avg += matrix[i+1][j]
                if j > 0:
                    current_avg += matrix[i][j-1]
                if j < n-1:
                    current_avg += matrix[i][j+1]
                # Update the maximum average found
                max_avg = max(max_avg, current_avg / n)
    return max_avg
```

