def maxAverageOfPath(matrix, n):
    max_avg = 0
    for i in range(n):
        for j in range(n):
            path_avg = cumulativeAverage(matrix, i, j, n)
            if path_avg > max_avg:
                max_avg = path_avg
    return max_avg

def cumulativeAverage(matrix, i, j, n):
    total = matrix[i][j]
    count = 1
    for r in range(max(0, i-1), min(n, i+2)):
        for c in range(max(0, j-1), min(n, j+2)):
            if (r, c) != (i, j):
                total += matrix[r][c]
                count += 1
    return total / count
```

