def maxAverageOfPath(matrix, n):
    def dp(x, y, k):
        if k == n * n:
            return matrix[x][y]
        if x < 0 or x >= n or y < 0 or y >= n:
            return float('-inf')
        up = dp(x-1, y, k+1)
        down = dp(x+1, y, k+1)
        left = dp(x, y-1, k+1)
        right = dp(x, y+1, k+1)
        return max(matrix[x][y] + up, matrix[x][y] + down, matrix[x][y] + left, matrix[x][y] + right)

    max_avg = float('-inf')
    for i in range(n):
        for j in range(n):
            max_avg = max(max_avg, dp(i, j, 0) / n)
    return max_avg
