        # Update the max1 and max2 based on the current number
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the min1 and min2 based on the current number
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
