    if i == n1: 
        return arr2[j + k - 1] 

    # If we reach the end of arr2, return the element from arr1
    if j == n2: 
        return arr1[i + k - 1] 

    # If k is 1, return the smaller of the two elements at the beginning of arr1 and arr2
    if k == 1: 
        return min(arr1[i], arr2[j]) 

    # Recursively find the kth element in the remaining sections of arr1 and arr2
    return find_kth(arr1, arr2, n1 - 1, n2 - 1, k - 1) 

