def find_kth(arr1, arr2, k1, k2, k):
    # If both arrays are empty, return -1
    if not arr1 and not arr2:
        return -1

    # Base cases for recursion
    if k1 == 0:
        return arr2[k2 - 1]
    if k2 == 0:
        return arr1[k1 - 1]

    # Find the middle elements
    mid1, mid2 = arr1[(k1 - 1) // 2], arr2[(k2 - 1) // 2]

    # Compare the middle elements of arr1 and arr2
    if mid1 <= mid2:
        # If mid1 is the kth element, return mid1
        if (k1 + k2) == k:
            return mid1
        # If mid1 is not the kth element, search in the right half of arr1
        else:
            return find_kth(arr1[(k1 + k2) // 2 :], arr2, k1 - ((k1 + k2) // 2) + 1, k2, k)
    else:
        # If mid2 is the kth element, return mid2
        if (k1 + k2) == k:
            return mid2
        # If mid2 is not the kth element, search in the left half of arr2
        else:
            return find_kth(arr1, arr2[:k2], k1, k2 - ((k1 + k2) // 2), k)
```

