def find_kth(A, B, m, n, k):
    if m == 0:
        return B[k-1]
    if n == 0:
        return A[k-1]
    if k == 1:
        return min(A[0], B[0])
    x = min(m, k // 2)
    y = min(n, k // 2)
    if A[x-1] <= B[y-1]:
        return find_kth(A[x:], B, m-x, n, k-x+1)
    else:
        return find_kth(A, B[y:], m, n-y, k-y+1)
