def find_First_Missing(nums, start, end):
    # Check if the array is empty or has no elements
    if not nums or start == end:
        return 0

    # Create a boolean array to mark the presence of numbers
    marked = [False] * (end + 1)

    # Mark the presence of numbers in the array
    for num in nums:
        if start <= num <= end:
            marked[num] = True

    # Find the missing number
    for num in range(start, end + 1):
        if not marked[num]:
            return num

    # If all numbers are present, return the next number
    return end + 1

