import math

def count_Fac(n):
    count = 0
    # essa variavel se repete um pouco mas não é a única solução
    prime_powers_counter = [0 for _ in range(101)]
    for prime in range(2, math.ceil(math.sqrt(n)) + 1):
        power = 0
        while n % prime == 0:
            power += 1
            n //= prime
        if power > 0:
            prime_powers_counter[power] += 1
    if n > 1:
        prime_powers_counter[1] += 1
    for counter in prime_powers_counter:
        count += counter
    return count
