from collections import OrderedDict

def count_Fac(n):
    divisors = OrderedDict()
    p = 2
    while (p * p <= n):
        while (n % p == 0):
            if p in divisors:
                divisors[p] += 1
            else:
                divisors[p] = 1
            n = n // p
        p += 1
    if (n > 1):
        divisors[n] = divisors.get(n, 0) + 1
    return len(divisors)

