def dealnnoy_num(n, k):
    # Initialize a list to store the delannoy numbers
    dp = [[0 for _ in range(k+1)] for _ in range(n+1)]

    # Base cases
    for i in range(n+1):
        for j in range(k+1):
            if i == 0:
                if j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = dp[i][j-1]
            elif j == 0:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i][j-1] + dp[i-1][j] + dp[i-1][j-1]

    return dp[n][k]

