    for i in range(n + 1):
        for j in range(min(i + 1, k + 1)):
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - 1][j - 1] + dp[i - 1][j]

