def dealnnoy_num(n, m):
    # Initialize a 3D matrix with zeros
    dp = [[[0 for _ in range(m+1)] for _ in range(n+1)] for _ in range(m+1)]

    # Base cases
    dp[0][0][0] = 1
    for i in range(n+1):
        dp[i][0][0] = 1

    for i in range(1, n+1):
        for j in range(1, m+1):
            for k in range(m+1):
                # Calculate delannoy number using recursion
                dp[i][j][k] = dp[i][j-1][k-1] + dp[i-1][j-1][k] + dp[i-1][j][k-1] + dp[i-1][j-1][k-1]

    return dp[n][m][m]
```

