    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                dp[i][j] = 0
            elif j == 0 or i == j:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j] + dp[i][j - 1]

    # Return the nth delannoy number
    return dp[n][m]
