def find_Min_Swaps(arr, n):
    # Initialize a list to keep track of positions of ones
    pos = [0] * n
    count = 0

    # Find the positions of ones
    for i in range(n):
        if arr[i] == 1:
            pos[i] = i
            count += 1

    # If count of ones is odd, it's impossible to sort
    if count % 2 != 0:
        return -1

    # Initialize the list to keep count of minimum swaps needed for each position of one
    min_swaps = [0] * n

    # Iterate through each position of one
    for i in range(n):
        # Find the position of the smallest one to the right beyond 'i'
        smallest_right = n
        for j in range(i + 1, n):
            if arr[j] == 1 and j < smallest_right:
                smallest_right = j

        # Add 'count - (j - i)' to min_swaps for each one that is not sorted
        if smallest_right != n:
            min_swaps[i] = count - (smallest_right - i - 1)

    # Return the minimum swaps needed
    return min(min_swaps)
```

