def rencontres_number(n, k):
    # Initialize the matrix dp
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(1, n + 1):
        dp[i][i] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if i == j:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - 1][j] * (i - 1) - dp[i - 2][j - 1]

    return dp[n][k - 1]
