def sum_of_square(n):
    # Initialize a 2D list with zeros
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(n + 1):
        dp[0][i] = 1

    for r in range(1, n + 1):
        for k in range(r + 1):
            dp[r][k] = dp[r - 1][k] + (r * dp[r - 1][k - 1]) / k

    # Calculate the sum of squares of binomial co-efficients
    return int(sum(sum(dp[i][k] ** 2 for k in range(i + 1)) for i in range(n + 1)))
