def lobb_num(n, k):
    # Initialize a 2D list to store intermediate results
    results = [[0] * (k + 1) for _ in range(n + 1)]

    # Base cases: lobb number for n=0 is 1
    for j in range(1, k + 1):
        results[0][j] = 0

    # Calculate lobb number using a bottom-up dynamic programming approach
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if j <= i:
                results[i][j] = results[i-1][j] + (j * i**3)
            else:
                results[i][j] = results[i][j-1]

    # Return the result
    return results[n][k]
```

